using BARANG.Core.Domain.Pricing;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class PricingConfiguration
{
    internal static void Company<T>(EntityTypeBuilder<T> b) where T : class { b.Property("CompanyId").HasColumnName("company_id"); }
    internal static void Money<T>(EntityTypeBuilder<T> b, string property, string column) where T : class => b.Property<decimal>(property).HasColumnName(column).HasPrecision(18, 2);
}
internal sealed class TariffConfiguration : IEntityTypeConfiguration<Tariff>
{
    public void Configure(EntityTypeBuilder<Tariff> b) { b.ToTable("tariffs", t => { t.HasCheckConstraint("ck_tariffs_amount", "amount >= 0"); t.HasCheckConstraint("ck_tariffs_period", "valid_to IS NULL OR valid_to >= valid_from"); }); b.HasKey(x => x.Id); b.Property(x=>x.Id).HasColumnName("id"); PricingConfiguration.Company(b); b.Property(x=>x.TariffType).HasColumnName("tariff_type").HasConversion<string>().HasMaxLength(32); b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(80); b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id"); b.Property(x=>x.PriceGroupId).HasColumnName("price_group_id"); b.Property(x=>x.PrintPositionCode).HasColumnName("print_position_code").HasMaxLength(64); b.Property(x=>x.PrintMethodCode).HasColumnName("print_method_code").HasMaxLength(64); PricingConfiguration.Money(b,nameof(Tariff.Amount),"amount"); b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength(); b.Property(x=>x.ValidFrom).HasColumnName("valid_from"); b.Property(x=>x.ValidTo).HasColumnName("valid_to"); b.Property(x=>x.IsActive).HasColumnName("is_active"); b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc"); b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc"); b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();
        // SyncPhase3Model added these required compatibility columns before the current Tariff aggregate replaced that model.
        b.Property<Guid>("LogicalTariffId").HasColumnName("logical_tariff_id").HasDefaultValueSql("gen_random_uuid()");
        b.Property<string>("Name").HasColumnName("name").HasMaxLength(200).HasDefaultValue("").IsRequired();
        b.Property<int>("VersionNumber").HasColumnName("version_number").HasDefaultValue(1);
        b.HasIndex(x=>new{x.CompanyId,x.TariffType,x.Code,x.ValidFrom}).HasDatabaseName("ix_tariffs_resolution"); b.HasOne<Domain.Catalog.ProductVariant>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductVariantId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); b.HasOne<Domain.Lookups.LookupValue>().WithMany().HasForeignKey(x=>x.PriceGroupId).OnDelete(DeleteBehavior.Restrict); }
}
internal sealed class DiscountRuleConfiguration : IEntityTypeConfiguration<DiscountRule>
{
    public void Configure(EntityTypeBuilder<DiscountRule> b) { b.ToTable("discount_rules",t=>{t.HasCheckConstraint("ck_discount_rules_value","value >= 0 AND (discount_type <> 'Percentage' OR value <= 100)");t.HasCheckConstraint("ck_discount_rules_period","valid_to IS NULL OR valid_to >= valid_from");}); b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");PricingConfiguration.Company(b);b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(80);b.Property(x=>x.DiscountType).HasColumnName("discount_type").HasConversion<string>().HasMaxLength(24);b.Property(x=>x.Scope).HasColumnName("scope").HasConversion<string>().HasMaxLength(24);b.Property(x=>x.CustomerId).HasColumnName("customer_id");b.Property(x=>x.CustomerGroupId).HasColumnName("customer_group_id");b.Property(x=>x.Source).HasColumnName("source").HasConversion<string>().HasMaxLength(24);PricingConfiguration.Money(b,nameof(DiscountRule.Value),"value");b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength();b.Property(x=>x.ValidFrom).HasColumnName("valid_from");b.Property(x=>x.ValidTo).HasColumnName("valid_to");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.Code,x.ValidFrom}).HasDatabaseName("ix_discount_rules_resolution");b.HasOne<Domain.Lookups.LookupValue>().WithMany().HasForeignKey(x=>x.CustomerGroupId).OnDelete(DeleteBehavior.Restrict); }
}
internal sealed class TaxRuleConfiguration : IEntityTypeConfiguration<TaxRule>
{
    public void Configure(EntityTypeBuilder<TaxRule> b) { b.ToTable("tax_rules",t=>{t.HasCheckConstraint("ck_tax_rules_rate","rate_percent >= 0 AND rate_percent <= 100");t.HasCheckConstraint("ck_tax_rules_period","valid_to IS NULL OR valid_to >= valid_from");});b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");PricingConfiguration.Company(b);b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(80);b.Property(x=>x.TaxStatusCode).HasColumnName("customer_tax_status_code").HasMaxLength(80);PricingConfiguration.Money(b,nameof(TaxRule.RatePercent),"rate_percent");b.Property(x=>x.IsExempt).HasColumnName("is_exempt");b.Property(x=>x.ValidFrom).HasColumnName("valid_from");b.Property(x=>x.ValidTo).HasColumnName("valid_to");b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.Code,x.TaxStatusCode,x.ValidFrom}).HasDatabaseName("ix_tax_rules_resolution"); }
}
internal sealed class OrderPriceSnapshotConfiguration : IEntityTypeConfiguration<OrderPriceSnapshot>
{
    public void Configure(EntityTypeBuilder<OrderPriceSnapshot> b) { b.ToTable("order_price_snapshots");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");PricingConfiguration.Company(b);b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength();foreach(var p in new[]{nameof(OrderPriceSnapshot.RawProductTotal),nameof(OrderPriceSnapshot.PrintTotal),nameof(OrderPriceSnapshot.AdditionalServiceTotal),nameof(OrderPriceSnapshot.PackagingTotal),nameof(OrderPriceSnapshot.ShippingTotal),nameof(OrderPriceSnapshot.Subtotal),nameof(OrderPriceSnapshot.DiscountTotal),nameof(OrderPriceSnapshot.TaxableTotal),nameof(OrderPriceSnapshot.TaxTotal),nameof(OrderPriceSnapshot.FinalTotal),nameof(OrderPriceSnapshot.TaxRatePercent)}) PricingConfiguration.Money(b,p,System.Text.Json.JsonNamingPolicy.SnakeCaseLower.ConvertName(p));b.Property(x=>x.IsTaxExempt).HasColumnName("is_tax_exempt");b.Property(x=>x.IsCurrent).HasColumnName("is_current");b.Property(x=>x.IsFinalized).HasColumnName("is_finalized");b.Property(x=>x.CalculatedAtUtc).HasColumnName("calculated_at_utc");b.Property(x=>x.FinalizedAtUtc).HasColumnName("finalized_at_utc");b.Property(x=>x.CalculationVersion).HasColumnName("calculation_version");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>x.OrderId).HasFilter("is_current").IsUnique().HasDatabaseName("uq_order_price_snapshots_current");b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); }
}
internal sealed class OrderItemPriceSnapshotConfiguration : IEntityTypeConfiguration<OrderItemPriceSnapshot>
{
    public void Configure(EntityTypeBuilder<OrderItemPriceSnapshot> b) { b.ToTable("order_item_price_snapshots");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");PricingConfiguration.Company(b);b.Property(x=>x.OrderPriceSnapshotId).HasColumnName("order_price_snapshot_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");foreach(var p in new[]{nameof(OrderItemPriceSnapshot.RawProductTotal),nameof(OrderItemPriceSnapshot.PrintTotal),nameof(OrderItemPriceSnapshot.AdditionalServiceTotal),nameof(OrderItemPriceSnapshot.Subtotal),nameof(OrderItemPriceSnapshot.DiscountAllocated),nameof(OrderItemPriceSnapshot.TaxableAmount),nameof(OrderItemPriceSnapshot.TaxAmount),nameof(OrderItemPriceSnapshot.FinalTotal)}) PricingConfiguration.Money(b,p,System.Text.Json.JsonNamingPolicy.SnakeCaseLower.ConvertName(p));b.HasIndex(x=>new{x.OrderPriceSnapshotId,x.OrderItemId}).IsUnique();b.HasOne<OrderPriceSnapshot>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderPriceSnapshotId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); }
}
internal sealed class PriceComponentSnapshotConfiguration : IEntityTypeConfiguration<PriceComponentSnapshot>
{
    public void Configure(EntityTypeBuilder<PriceComponentSnapshot> b) { b.ToTable("price_component_snapshots");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");PricingConfiguration.Company(b);b.Property(x=>x.OrderPriceSnapshotId).HasColumnName("order_price_snapshot_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.OrderPrintOperationId).HasColumnName("order_print_operation_id");b.Property(x=>x.TariffId).HasColumnName("tariff_id");b.Property(x=>x.PricingRuleId).HasColumnName("pricing_rule_id");b.Property(x=>x.PricingRuleVersion).HasColumnName("pricing_rule_version");b.Property(x=>x.ComponentType).HasColumnName("component_type").HasConversion<string>().HasMaxLength(32);b.Property(x=>x.TariffCode).HasColumnName("tariff_code").HasMaxLength(80);PricingConfiguration.Money(b,nameof(PriceComponentSnapshot.UnitAmount),"unit_amount");b.Property(x=>x.Quantity).HasColumnName("quantity").HasPrecision(18,4);PricingConfiguration.Money(b,nameof(PriceComponentSnapshot.TotalAmount),"total_amount");b.HasIndex(x=>x.OrderPriceSnapshotId);b.HasOne<OrderPriceSnapshot>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderPriceSnapshotId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict); }
}
